INSERT INTO "revisions" VALUES('dd09108518c1923392a6db324410b9c3c28f1515d69aeb6d21d826a3a7f0c440','histories::library_app','{"entry":"main.nex","files":{"@pkg/numbers/model.nex":"module histories::numbers;pub fn answer()->i64{return 42;}\n","@std/text.nex":"module std::text;\n\npub fn starts_with(value: str, prefix: str) -> bool {\n  if len(prefix) > len(value) { return false; }\n  return slice(value, 0, len(prefix)) == prefix;\n}\n\npub fn ends_with(value: str, suffix: str) -> bool {\n  if len(suffix) > len(value) { return false; }\n  return slice(value, len(value) - len(suffix), len(suffix)) == suffix;\n}\n\npub fn join(values: list<str>, separator: str) -> str {\n  var result: str = \"\";\n  var i: i64 = 0;\n  while i < len(values) {\n    if i > 0 { result = result + separator; }\n    result = result + values[i];\n    i = i + 1;\n  }\n  return result;\n}\n\ntest fn text_test() -> unit {\n  assert(starts_with(\"Привет 🦊\", \"При\"));\n  assert(ends_with(\"Привет 🦊\", \"🦊\"));\n  assert(join([\"a\", \"b\"], \",\") == \"a,b\");\n}\n","main.nex":"module histories::library_app;import \"numbers/model.nex\" as numbers;import \"std/text.nex\" as text;\nserver fn main()->i64 !{task,fs}{assert(numbers::answer()==42);assert(text::join([\"NEX\",\"🧠\"],\" \")==\"NEX 🧠\");let f:file=unwrap(file_open_read(\"input\"));assert(unwrap(file_read(f,6))==utf8_bytes(\"abcdef\"));assert(file_close(f));return numbers::answer();}\n\nclient fn client_value()->i64{return 42;}\ntest fn pure_answer()->unit{assert(42>41);}\n"},"schema":"nex.sources/1"}','/Users/sae/projects/NEX/build/genuine023-expanded179-capture-v6/origins/locked-library/main.nex','2026-10-25T16:46:56.788Z','0.23');
